 * one target, and it is the target.
 *
 * @category conversions
 * @since 0.1.0
 * @slop
 */
export const sole = (value) => {
    const named = new Set(NarrowedCheck.lex(value).filter(NarrowedCheck.names));
    const [only] = named;
    return named.size === 1 ? only : undefined;
