 * four values and not four leaves that took one each. That is what makes a
 * four-state judgement fit a line.
 */
const leaves = (value, path, into, left) => {
    const took = (rendered) => {
        const seen = into.get(path);
        if (seen === undefined)
            into.set(path, [rendered]);
        else
            seen.push(rendered);
    };
    if (counted(value) || left === 0)
        return took(scalar(value));
    if (Array.isArray(value)) {
        for (const item of value)
            leaves(item, `${path}[]`, into, left - 1);
        return;
    }
    const record = value;
    const keys = Object.keys(record).sort();
    // `{}` and not `{…}`: nothing was elided, the record is empty, and a reader
    // that cannot tell those apart reads an empty result as a hidden one.
    if (keys.length === 0)
        return took("{}");
    for (const key of keys) {
        const next = /^[A-Za-z_$][\w$]*$/.test(key)
