    const tally = new Map();
    for (const value of values)
        tally.set(value, (tally.get(value) ?? 0) + 1);
    const all = [...tally.entries()];
    const named = all.slice(0, distinct).map(([value, count]) => count === 1 ? value : `${value}×${count}`);
